mapper.select:
SELECT id, conversation_id, sender_id, client_msg_id, seq, msg_type, content,
       created_at, recalled_at, recalled_by, reply_to_id, reply_sender_id, reply_preview
FROM im_message
WHERE conversation_id = #{conversationId}
  AND seq > #{afterSeq}
ORDER BY seq ASC
LIMIT #{limit}

SELECT COALESCE(MAX(seq), 0)
FROM im_message
WHERE conversation_id = #{conversationId}

SELECT id, conversation_id, sender_id, client_msg_id, seq, msg_type, content,
       created_at, recalled_at, recalled_by, reply_to_id, reply_sender_id, reply_preview
FROM im_message
WHERE conversation_id = #{conversationId}
  AND recalled_at IS NULL
  AND msg_type IN (1, 6)
  AND seq < #{beforeSeq}
  AND content LIKE #{pattern} ESCAPE '!'
ORDER BY seq DESC
LIMIT #{limit}
